```java
public class ViewConstructorDetector extends Detector implements Detector.JavaPsiScanner {
    private static final Implementation IMPLEMENTATION = new Implementation(
            ViewConstructorDetector.class,
            Scope.JAVA_FILE_SCOPE);

    /** Missing view constructor */
    public static final Issue ISSUE = Issue.create(
            "ViewConstructor",
            "Missing View constructors for XML inflation",
            "Some layout tools (such as the Android layout editor) need to find a constructor with one of the following signatures:\n" +
            "* `View(Context context)`\n" +
            "* `View(Context context, AttributeSet attrs)`\n" +
            "* `View(Context context, AttributeSet attrs, int defStyle)`\n" +
            "\n" +
            "If your custom view needs to perform initialization which does not apply when used in a layout editor, you can surround the given code with a check to see if `View#isInEditMode()` is false, since that method will return `false` at runtime but true within a user interface editor.",
            Category.CORRECTNESS,
            6,
            Severity.WARNING,
            IMPLEMENTATION);

    @Override
    public List<Class<? extends PsiElement>> getApplicablePsiTypes() {
        return Collections.singletonList(PsiClass.class);
    }

    @Override
    public JavaElementVisitor createPsiVisitor(@NotNull JavaContext context) {
        return new JavaElementVisitor() {
            @Override
            public void visitClass(PsiClass aClass) {
                if (aClass.isInterface() || aClass.isEnum() || aClass.isAnnotationType()
                        || aClass.hasModifierProperty(PsiModifier.ABSTRACT)) {
                    return;
                }

                if (!InheritanceUtil.isInheritor(aClass, "android.view.View")) {
                    return;
                }

                // skip View itself and classes with no source position
                if (aClass.getQualifiedName() == null
                        || aClass.getQualifiedName().equals("android.view.View")) {
                    return;
                }

                for (PsiMethod constructor : aClass.getConstructors()) {
                    if (constructor.hasModifierProperty(PsiModifier.PUBLIC)
                            && hasMatchingSignature(constructor)) {
                        return;
                    }
                }

                context.report(ISSUE, aClass, context.getNameLocation(aClass),
                        "Custom view `" + aClass.getName() + "` is missing constructor "
                        + "accepting `Context`, `AttributeSet`, or `int defStyle` parameter(s)");
            }
        };
    }

    private static boolean hasMatchingSignature(PsiMethod constructor) {
        PsiParameterList params = constructor.getParameterList();
        int count = params.getParametersCount();
        if (count == 0 || count > 3) {
            return false;
        }
        PsiParameter[] ps = params.getParameters();
        if (!isType(ps[0].getType(), "android.content.Context")) {
            return false;
        }
        if (count == 1) {
            return true;
        }
        if (!isType(ps[1].getType(), "android.util.AttributeSet")) {
            return false;
        }
        if (count == 2) {
            return true;
        }
        return isInt(ps[2].getType());
    }

    private static boolean isType(PsiType type, String fullyQualifiedName) {
        return type instanceof PsiClassType
                && fullyQualifiedName.equals(((PsiClassType) type).resolve()
                        != null ? ((PsiClassType) type).getCanonicalText() : null);
    }

    private static boolean isInt(PsiType type) {
        return PsiType.INT.equals(type);
    }
}
```

